    "name": "CircuitBreaker.java",
    "content": "package com.artificialintelligence.patterns.apigateway;\n\nimport java.util.function.Supplier;\n\n/**\n * Simple circuit breaker: opens after a threshold of failures and rejects calls\n * (returning a fallback) until a reset timeout elapses, then probes in half-open state.\n */\npublic class CircuitBreaker {\n\n    public enum State { CLOSED, OPEN, HALF_OPEN }\n\n    private final int failureThreshold;\n    private final long resetTimeoutMs;\n\n    private State state = State.CLOSED;\n    private int failures = 0;\n    private long openedAt = 0L;\n    private final Object lock = new Object();\n\n    public CircuitBreaker(int failureThreshold, long resetTimeoutMs) {\n        if (failureThreshold <= 0) throw new IllegalArgumentException(\"failureThreshold must be > 0\");\n        this.failureThreshold = failureThreshold;\n        this.resetTimeoutMs = resetTimeoutMs;\n    }\n\n    public <T> T call(Supplier<T> action, Supplier<T> fallback) {\n        synchronized (lock) {\n            if (state == State.OPEN) {\n                if (System.currentTimeMillis() - openedAt >= resetTimeoutMs) {\n                    state = State.HALF_OPEN;\n                } else {\n                    return fallback.get();\n                }\n            }\n        }\n        try {\n            T result = action.get();\n            onSuccess();\n            return result;\n        } catch (RuntimeException e) {\n            onFailure();\n            return fallback.get();\n        }\n    }\n\n    private void onSuccess() {\n        synchronized (lock) {\n            failures = 0;\n            if (state == State.HALF_OPEN) {\n                state = State.CLOSED;\n            }\n        }\n    }\n\n    private void onFailure() {\n        synchronized (lock) {\n            failures++;\n            if (state == State.HALF_OPEN || failures >= failureThreshold) {\n                state = State.OPEN;\n                openedAt = System.currentTimeMillis();\n            }\n        }\n    }\n\n    public State state() {\n        synchronized (lock) {\n            if (state == State.OPEN && System.currentTimeMillis() - openedAt >= resetTimeoutMs) {\n                return State.HALF_OPEN;\n            }\n            return state;\n        }\n    }\n\n    public void reset() {\n        synchronized (lock) {\n            state = State.CLOSED;\n            failures = 0;\n            openedAt = 0L;\n        }\n    }\n}\n"
